// ===== Featured product data =====
const products = [
  { id: 1, name: "Stoneware Mug Set", category: "kitchen", price: 48, oldPrice: null, badge: "New", art: "art-1", rating: 4.8, reviews: 124 },
  { id: 2, name: "Linen Throw Blanket", category: "home", price: 129, oldPrice: 165, badge: "Sale", art: "art-2", rating: 4.9, reviews: 86 },
  { id: 3, name: "Oak Cutting Board", category: "kitchen", price: 64, oldPrice: null, badge: null, art: "art-3", rating: 4.7, reviews: 212 },
  { id: 4, name: "Merino Crewneck", category: "apparel", price: 145, oldPrice: null, badge: "New", art: "art-4", rating: 4.8, reviews: 58 },
  { id: 5, name: "Ceramic Vase, Tall", category: "home", price: 72, oldPrice: 95, badge: "Sale", art: "art-5", rating: 4.6, reviews: 41 },
  { id: 6, name: "Cotton Bath Towel", category: "home", price: 38, oldPrice: null, badge: null, art: "art-6", rating: 4.7, reviews: 198 },
  { id: 7, name: "Wool Overshirt", category: "apparel", price: 220, oldPrice: null, badge: "Best seller", art: "art-7", rating: 4.9, reviews: 142 },
  { id: 8, name: "Brass Pepper Mill", category: "kitchen", price: 56, oldPrice: null, badge: null, art: "art-8", rating: 4.5, reviews: 33 },
];

const heartIcon = `<svg aria-hidden="true" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78Z"/></svg>`;

function badgeClass(b) {
  if (!b) return "";
  if (b.toLowerCase() === "sale") return "is-sale";
  if (b.toLowerCase() === "new") return "is-new";
  return "";
}

function renderProducts(filter = "all") {
  const grid = document.getElementById("productGrid");
  if (!grid) return;
  const items = products.filter(p => filter === "all" || p.category === filter);
  grid.innerHTML = items.map(p => `
    <li class="product">
      <div class="product-media ${p.art}">
        ${p.badge ? `<span class="product-badge ${badgeClass(p.badge)}">${p.badge}</span>` : ""}
        <button type="button" class="product-fav" aria-pressed="false" aria-label="Add ${p.name} to favorites">${heartIcon}</button>
      </div>
      <div class="product-info">
        <span class="product-cat">${p.category}</span>
        <h3 class="product-name"><a href="#" style="text-decoration:none;color:inherit">${p.name}</a></h3>
        <p class="product-price">
          <span>$${p.price}</span>
          ${p.oldPrice ? `<span class="price-was"><span class="visually-hidden">Original price </span>$${p.oldPrice}</span>` : ""}
        </p>
        <p class="product-rating">
          <span class="stars" aria-hidden="true">★★★★★</span>
          <span><span class="visually-hidden">Rated </span>${p.rating}<span class="visually-hidden"> out of 5</span> (${p.reviews})</span>
        </p>
      </div>
    </li>
