    const pad = n => String(n).padStart(2, "0");
    el.textContent = `${d}d ${pad(h)}:${pad(m)}:${pad(s)}`;
  }
  tick();
  setInterval(tick, 1000);
}

// ===== Newsletter form =====
function setupNewsletter() {
  const form = document.getElementById("newsletterForm");
  const input = document.getElementById("email");
  const status = document.getElementById("newsletter-status");
  if (!form) return;

  form.addEventListener("submit", (e) => {
    e.preventDefault();
    const value = input.value.trim();
    const valid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
    status.classList.remove("is-error");
    if (!valid) {
      status.textContent = "Please enter a valid email address.";
      status.classList.add("is-error");
      input.focus();
      return;
    }
    status.textContent = `Thanks! We'll send the next letter to ${value}.`;
    form.reset();
  });
}

// ===== Cart counter (just a tiny demo) =====
function setupCart() {
  const btn = document.getElementById("cartButton");
  const count = document.getElementById("cartCount");
  if (!btn || !count) return;
  let n = parseInt(count.textContent, 10) || 0;
  btn.addEventListener("click", () => {
    n += 1;
    count.textContent = n;
    btn.setAttribute("aria-label", `Shopping bag, ${n} item${n === 1 ? "" : "s"}`);
  });
}

document.addEventListener("DOMContentLoaded", () => {
  renderProducts("all");
  setupTabs();
  startCountdown();
  setupNewsletter();
  setupCart();
});

