.story-lead .story-link { display: flex; flex-direction: column; height: 100%; }
.story-art { aspect-ratio: 16 / 10; }
.story-lead .story-art { aspect-ratio: 4/3; flex: 1; min-height: 280px; }
.story-art-1 { background: linear-gradient(160deg, #d4c4a8, #8a6f50); }
.story-art-2 { background: linear-gradient(160deg, #c8b8d4, #6e5e88); }
.story-art-3 { background: linear-gradient(160deg, #506b5e, #2d4a3e); }
.story-art-4 { background: linear-gradient(160deg, #e8c8a8, #c08858); }
.story-body { padding: 20px 22px 24px; }
.story-meta {
