  gap: 48px;
  padding-bottom: 40px;
  border-bottom: 1px solid rgba(255,255,255,.1);
}
.footer-brand .brand { color: #fff; font-size: 1.1rem; }
.footer-brand p { color: #aaa49a; margin-top: 14px; max-width: 36ch; }
.footer-nav { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; }
.footer-h {
  font-family: var(--font-sans);
  font-size: .82rem;
  text-transform: uppercase;
  letter-spacing: .12em;
  color: #fff;
  margin: 0 0 16px;
  font-weight: 700;
}
.footer-nav ul { list-style: none; padding: 0; margin: 0; display: grid; gap: 10px; }
.footer-nav a { text-decoration: none; color: #cfc9be; font-size: .92rem; }
.footer-nav a:hover { color: #fff; }
.footer-bottom {
  display: flex; justify-content: space-between; gap: 16px;
  padding-top: 24px;
  color: #8a8478; flex-wrap: wrap;
}
.footer-bottom a { color: inherit; }

/* ================= Responsive ================= */
@media (max-width: 1024px) {
  .hero-inner { grid-template-columns: 1fr; gap: 48px; }
  .hero-visual { min-height: 360px; max-width: 520px; }
  .product-grid { grid-template-columns: repeat(3, 1fr); }
  .category-grid { grid-template-columns: repeat(3, 1fr); }
  .deals-grid { grid-template-columns: 1fr 1fr; }
  .deal-feature { grid-row: auto; grid-column: span 2; }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .story-lead { grid-row: auto; grid-column: span 2; }
  .newsletter-inner { grid-template-columns: 1fr; gap: 32px; }
}

@media (max-width: 720px) {
  .primary-nav { display: none; }
  .header-inner { gap: 12px; justify-content: space-between; }
  .product-grid { grid-template-columns: repeat(2, 1fr); gap: 16px; }
  .category-grid { grid-template-columns: repeat(2, 1fr); }
  .deals-grid { grid-template-columns: 1fr; }
  .deal-feature { grid-column: auto; }
  .editorial-grid { grid-template-columns: 1fr; }
  .story-lead { grid-column: auto; }
  .footer-inner { grid-template-columns: 1fr; gap: 32px; }
  .footer-nav { grid-template-columns: repeat(3, 1fr); gap: 16px; }
  .hero-stats { flex-wrap: wrap; gap: 20px; }
  .section-head { align-items: flex-start; }
  .hero { padding: 32px 0 56px; }
  .featured, .deals, .editorial, .newsletter { padding: 56px 0; }
}

@media (max-width: 420px) {
  .footer-nav { grid-template-columns: 1fr 1fr; }
  .newsletter-form { grid-template-columns: 1fr; }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; animation: none !important; }
}

/* Forced colors */
@media (forced-colors: active) {
  .btn-primary, .tab.is-active { border: 1px solid CanvasText; }
  .product, .story, .deal { border: 1px solid CanvasText; }
}
