', direction=None, fact=None, file_name='/workspace/sandbox/skills/building-accessible-ui/shopping-home-page--framework-vanilla-js--style-modern/claude-opus-4.7__s2/styles.css', full_command_text=None, hook_message=None, intention='Edit file', new_file_contents=':root {
  --bg: #faf8f5;
  --bg-alt: #f1ede6;
  --surface: #ffffff;
  --ink: #1a1a1a;
  --ink-2: #4a4a4a;
  --ink-3: #6b6b6b;
  --line: #e6e1d9;
  --accent: #2d4a3e;
  --accent-2: #d97757;
  --warn: #b8351f;
  --radius: 14px;
  --radius-lg: 22px;
  --shadow-sm: 0 1px 2px rgba(20, 20, 20, .06), 0 2px 8px rgba(20, 20, 20, .04);
  --shadow-md: 0 4px 12px rgba(20, 20, 20, .08), 0 12px 32px rgba(20, 20, 20, .06);
  --font-sans: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-serif: ui-serif, Georgia, "Times New Roman", serif;
}

* { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; display: block; }

a { color: inherit; }
a:focus-visible, button:focus-visible, input:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  border-radius: 4px;
}

.container {
  width: 100%;
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 24px;
}

.visually-hidden {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap; border: 0;
}

/* Skip link */
.skip-link {
  position: absolute;
  left: 12px; top: -40px;
  background: var(--ink); color: #fff;
  padding: 8px 14px;
  border-radius: 8px;
  text-decoration: none;
  z-index: 1000;
  transition: top .15s ease;
}
.skip-link:focus { top: 12px; }

/* ================= Header ================= */
.site-header {
  position: sticky; top: 0; z-index: 50;
  background: rgba(250, 248, 245, 0.85);
  backdrop-filter: saturate(160%) blur(10px);
  border-bottom: 1px solid var(--line);
}
.header-inner {
  display: flex; align-items: center;
  gap: 32px;
  height: 72px;
}
.brand {
  display: inline-flex; align-items: center; gap: 8px;
  font-weight: 700; text-decoration: none;
  font-size: 1.05rem; letter-spacing: -.01em;
}
.brand-mark {
  font-size: 1.4rem; color: var(--accent);
  transform: translateY(-1px);
}
.primary-nav { flex: 1; }
.primary-nav ul {
  display: flex; gap: 28px;
  list-style: none; padding: 0; margin: 0;
}
.primary-nav a {
  text-decoration: none;
  color: var(--ink-2);
  font-size: .95rem;
  padding: 6px 2px;
  position: relative;
}
.primary-nav a:hover { color: var(--ink); }
.primary-nav a:hover::after {
  content: ""; position: absolute; left: 0; right: 0; bottom: 0;
  height: 2px; background: var(--accent); border-radius: 2px;
}
.header-actions { display: flex; gap: 4px; align-items: center; }
.icon-btn {
  position: relative;
  background: transparent; border: 0;
  width: 40px; height: 40px;
  border-radius: 50%;
  display: inline-grid; place-items: center;
  color: var(--ink); cursor: pointer;
  transition: background .15s ease;
}
.icon-btn:hover { background: var(--bg-alt); }
.cart-count {
  position: absolute; top: 4px; right: 2px;
  background: var(--accent-2); color: #fff;
  font-size: .68rem; font-weight: 700;
  min-width: 18px; height: 18px;
  border-radius: 9px;
  display: inline-grid; place-items: center;
  padding: 0 5px;
  border: 2px solid var(--bg);
}

/* ================= Buttons / shared ================= */
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  gap: 8px;
  font-weight: 600; font-size: .95rem;
  padding: 14px 22px;
  border-radius: 999px;
  border: 1.5px solid transparent;
  text-decoration: none;
  cursor: pointer;
  transition: transform .12s ease, background .15s ease, color .15s ease;
}
.btn-sm { padding: 10px 18px; font-size: .88rem; }
.btn-primary { background: var(--ink); color: #fff; }
.btn-primary:hover { background: var(--accent); transform: translateY(-1px); }
.btn-ghost {
  background: transparent; color: var(--ink);
  border-color: var(--line);
}
.btn-ghost:hover { background: var(--surface); border-color: var(--ink); }

.eyebrow {
  text-transform: uppercase;
  letter-spacing: .14em;
  font-size: .75rem;
  font-weight: 600;
  color: var(--accent);
  margin: 0 0 10px;
}
.eyebrow-dark { color: var(--accent-2); }

h1, h2, h3 { font-family: var(--font-serif); letter-spacing: -.015em; line-height: 1.15; margin: 0; }
h2 { font-size: clamp(1.7rem, 2.6vw, 2.4rem); }
h3 { font-size: 1.15rem; }

.section-head {
  display: flex; align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 28px;
  flex-wrap: wrap;
}
.link-arrow {
  text-decoration: none;
  color: var(--ink);
  font-weight: 600;
  font-size: .92rem;
  border-bottom: 1.5px solid var(--ink);
  padding-bottom: 2px;
}
.link-arrow:hover { color: var(--accent); border-color: var(--accent); }

/* ================= Hero ================= */
.hero {
  padding: 56px 0 80px;
  background:
    radial-gradient(ellipse at 80% 0%, rgba(217, 119, 87, .12), transparent 50%),
    linear-gradient(180deg, var(--bg) 0%, var(--bg) 100%);
}
.hero-inner {
  display: grid;
  grid-template-columns: 1.05fr 1fr;
  gap: 64px;
  align-items: center;
}
.hero-copy h1 {
  font-size: clamp(2.4rem, 5.2vw, 4.2rem);
  margin-bottom: 22px;
}
.hero-copy h1 .accent { color: var(--accent); font-style: italic; }
.lede { font-size: 1.1rem; color: var(--ink-2); max-width: 46ch; margin: 0 0 32px; }
.hero-cta { display: flex; flex-wrap: wrap; gap: 12px; margin-bottom: 48px; }
.hero-stats {
  display: flex; gap: 36px; margin: 0;
  padding-top: 28px; border-top: 1px solid var(--line);
}
.hero-stats > div { display: grid; }
.hero-stats dt { font-weight: 700; font-size: .95rem; }
.hero-stats dd { margin: 0; color: var(--ink-3); font-size: .85rem; }

.hero-visual {
  position: relative;
  aspect-ratio: 1 / 1.05;
  min-height: 420px;
}
.hero-blob {
  position: absolute; inset: 8% 4% 4% 8%;
  background: linear-gradient(135deg, #e8d9c4, #d4b896 60%, #b89773);
  border-radius: 48% 52% 60% 40% / 50% 45% 55% 50%;
}
.hero-card {
  position: absolute;
  border-radius: var(--radius-lg);
  background: var(--surface);
  box-shadow: var(--shadow-md);
  overflow: hidden;
}
.hero-card::before {
  content: ""; position: absolute; inset: 0;
}
.hero-card-1 {
  width: 56%; aspect-ratio: 4/5;
  top: 4%; left: 0;
  background: linear-gradient(160deg, #d4c4a8, #a08868);
}
.hero-card-2 {
  width: 44%; aspect-ratio: 1;
  bottom: 8%; right: 4%;
  background: linear-gradient(135deg, #2d4a3e, #1e3329);
}
.hero-card-3 {
  width: 32%; aspect-ratio: 1;
  top: 8%; right: 12%;
  background: linear-gradient(160deg, #d97757, #b85a3e);
}

/* ================= Categories ================= */
.categories { padding: 64px 0 32px; }
.category-grid {
  list-style: none; padding: 0; margin: 0;
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 16px;
}
.category-tile {
  display: flex; align-items: flex-end;
  aspect-ratio: 4 / 5;
  border-radius: var(--radius);
  padding: 18px;
  text-decoration: none;
  color: var(--ink);
  font-weight: 600;
  position: relative;
  overflow: hidden;
  transition: transform .2s ease;
}
.category-tile:hover { transform: translateY(-3px); }
.category-tile span {
  position: relative; z-index: 1;
  background: rgba(255,255,255,.92);
  padding: 6px 12px;
  border-radius: 999px;
  font-size: .88rem;
}
.cat-1 { background: linear-gradient(160deg, #d4c4a8, #a08868); }
.cat-2 { background: linear-gradient(160deg, #c8b8d4, #8a7aa0); }
.cat-3 { background: linear-gradient(160deg, #2d4a3e, #1e3329); }
.cat-4 { background: linear-gradient(160deg, #d97757, #a85432); }
.cat-5 { background: linear-gradient(160deg, #e8dcc8, #b8a888); }

/* ================= Featured products ================= */
.featured { padding: 64px 0; }
.filter-tabs { display: flex; gap: 6px; flex-wrap: wrap; }
.tab {
  background: transparent; border: 1.5px solid var(--line);
  padding: 8px 16px; border-radius: 999px;
  font-size: .88rem; font-weight: 500;
  cursor: pointer; color: var(--ink-2);
  transition: all .15s ease;
}
.tab:hover { border-color: var(--ink); color: var(--ink); }
.tab.is-active {
  background: var(--ink); color: #fff; border-color: var(--ink);
}

.product-grid {
  list-style: none; padding: 0; margin: 0;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.product {
  background: var(--surface);
  border-radius: var(--radius);
  overflow: hidden;
  border: 1px solid var(--line);
  display: flex; flex-direction: column;
  transition: transform .2s ease, box-shadow .2s ease;
}
.product:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }
.product-media {
  aspect-ratio: 1;
  position: relative;
  overflow: hidden;
}
.product-badge {
  position: absolute; top: 12px; left: 12px;
  background: var(--ink); color: #fff;
  font-size: .7rem; font-weight: 700;
  padding: 5px 10px;
  border-radius: 999px;
  letter-spacing: .04em;
  text-transform: uppercase;
}
.product-badge.is-sale { background: var(--accent-2); }
.product-badge.is-new { background: var(--accent); }
.product-fav {
  position: absolute; top: 10px; right: 10px;
  width: 36px; height: 36px;
  background: rgba(255,255,255,.92);
  border: 0; border-radius: 50%;
  display: grid; place-items: center;
  cursor: pointer;
  transition: background .15s ease, transform .15s ease;
}
.product-fav:hover { background: #fff; transform: scale(1.05); }
.product-fav[aria-pressed="true"] svg { fill: var(--accent-2); stroke: var(--accent-2); }
.product-info {
  padding: 16px 18px 20px;
  display: flex; flex-direction: column; gap: 6px;
  flex: 1;
}
.product-cat { font-size: .75rem; color: var(--ink-3); text-transform: uppercase; letter-spacing: .08em; }
.product-name {
  font-family: var(--font-serif);
  font-size: 1.05rem;
  margin: 2px 0 4px;
}
.product-price { font-weight: 700; font-size: 1rem; margin: 0; }
.product-price .price-was {
  font-weight: 400; color: var(--ink-3);
  text-decoration: line-through;
  margin-left: 8px; font-size: .9rem;
}
.product-rating {
  font-size: .82rem; color: var(--ink-3);
  display: flex; align-items: center; gap: 4px;
  margin-top: auto; padding-top: 6px;
}
.stars { color: var(--accent-2); letter-spacing: 1px; }

/* product art (no images, gradients) */
.art-1 { background: linear-gradient(160deg, #e8d9c4, #b89773); }
.art-2 { background: linear-gradient(160deg, #2d4a3e, #1a2e25); }
.art-3 { background: linear-gradient(160deg, #d4c4a8, #8a6f50); }
.art-4 { background: linear-gradient(160deg, #d97757, #a04330); }
.art-5 { background: linear-gradient(160deg, #c8b8d4, #6e5e88); }
.art-6 { background: linear-gradient(160deg, #f0e0c8, #c8a878); }
.art-7 { background: linear-gradient(160deg, #506b5e, #2d4a3e); }
.art-8 { background: linear-gradient(160deg, #e0c8b0, #a08060); }

/* ================= Deals ================= */
.deals {
  background: var(--ink);
  color: #f1ede6;
  padding: 80px 0;
  margin-top: 32px;
}
.deals h2 { color: #fff; }
.deals .countdown {
  background: rgba(255,255,255,.08);
  border: 1px solid rgba(255,255,255,.14);
  padding: 10px 18px;
  border-radius: 999px;
  font-size: .9rem;
  display: inline-flex; gap: 12px; align-items: center;
}
.countdown-label { color: rgba(255,255,255,.7); }
.countdown-clock { font-weight: 700; font-variant-numeric: tabular-nums; letter-spacing: .04em; }

.deals-grid {
  display: grid;
  grid-template-columns: 1.6fr 1fr 1fr;
  gap: 24px;
}
.deal {
  background: #232323;
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex; flex-direction: column;
  transition: transform .2s ease;
}
.deal:hover { transform: translateY(-3px); }
.deal-feature { grid-row: span 2; }
.deal-art { aspect-ratio: 16 / 11; }
.deal-feature .deal-art { aspect-ratio: 16 / 13; }
.deal-art-1 { background: linear-gradient(160deg, #d4c4a8, #8a7560); }
.deal-art-2 { background: linear-gradient(160deg, #e8dcc8, #a89878); }
.deal-art-3 { background: linear-gradient(160deg, #506b5e, #2d4a3e); }
.deal-body { padding: 22px 24px 26px; flex: 1; display: flex; flex-direction: column; gap: 8px; }
.deal-tag {
  display: inline-block;
  background: var(--accent-2); color: #fff;
  font-size: .72rem; font-weight: 700;
  text-transform: uppercase; letter-spacing: .06em;
  padding: 4px 10px;
  border-radius: 999px;
  align-self: flex-start;
  margin-bottom: 4px;
}
.deal h3 { color: #fff; font-size: 1.4rem; }
.deal-feature h3 { font-size: 1.7rem; }
.deal-body p { color: rgba(255,255,255,.72); margin: 0; }
.deal-price { color: #fff !important; font-size: 1.1rem; margin-top: 4px !important; }
.deal-price .price-now { font-weight: 700; }
.deal-price .price-was { color: rgba(255,255,255,.65); text-decoration: line-through; margin-left: 10px; font-size: .92rem; }
.deals .link-arrow { color: #fff; border-color: rgba(255,255,255,.5); margin-top: 6px; align-self: flex-start; }
.deals .link-arrow:hover { color: var(--accent-2); border-color: var(--accent-2); }
.deal-feature .btn { margin-top: 10px; align-self: flex-start; }

/* ================= Editorial ================= */
.editorial { padding: 80px 0; }
.editorial-grid {
  display: grid;
  grid-template-columns: 1.2fr 1fr 1fr;
  grid-template-rows: auto auto;
  gap: 24px;
}
.story {
  border-radius: var(--radius);
  overflow: hidden;
  background: var(--surface);
  border: 1px solid var(--line);
  transition: transform .2s ease, box-shadow .2s ease;
}
.story:hover { transform: translateY(-3px); box-shadow: var(--shadow-md); }
.story-link { text-decoration: none; color: inherit; display: block; height: 100%; }
.story-lead { grid-row: span 2; display: flex; flex-direction: column; }
.story-lead .story-link { display: flex; flex-direction: column; height: 100%; }
.story-art { aspect-ratio: 16 / 10; }
.story-lead .story-art { aspect-ratio: 4/3; flex: 1; min-height: 280px; }
.story-art-1 { background: linear-gradient(160deg, #d4c4a8, #8a6f50); }
.story-art-2 { background: linear-gradient(160deg, #c8b8d4, #6e5e88); }
.story-art-3 { background: linear-gradient(160deg, #506b5e, #2d4a3e); }
.story-art-4 { background: linear-gradient(160deg, #e8c8a8, #c08858); }
.story-body { padding: 20px 22px 24px; }
.story-meta {
  font-size: .76rem; text-transform: uppercase;
  letter-spacing: .1em; color: var(--ink-3);
  font-weight: 600;
}
.story h3 { margin: 8px 0 6px; font-size: 1.15rem; }
.story-lead h3 { font-size: 1.7rem; margin-bottom: 10px; }
.story-body p { color: var(--ink-2); margin: 0 0 12px; }

/* ================= Newsletter ================= */
.newsletter {
  padding: 80px 0;
  background: var(--bg-alt);
}
.newsletter-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}
.newsletter h2 { margin-bottom: 12px; }
.newsletter p { color: var(--ink-2); margin: 0; max-width: 42ch; }
.newsletter-form {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 8px;
  position: relative;
}
.newsletter-form input {
  font: inherit;
  padding: 16px 20px;
  border-radius: 999px;
  border: 1.5px solid var(--line);
  background: #fff;
  min-width: 0;
}
.newsletter-form input:focus-visible {
  border-color: var(--accent);
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}
.form-status {
  grid-column: 1 / -1;
  margin: 6px 0 0 16px;
  font-size: .9rem;
  color: var(--accent);
  min-height: 1.4em;
}
.form-status.is-error { color: var(--warn); }

/* ================= Footer ================= */
.site-footer {
  background: var(--ink);
  color: #cfc9be;
  padding: 64px 0 24px;
}
.footer-inner {
  display: grid;
  grid-template-columns: 1.3fr 2fr;
  gap: 48px;
  padding-bottom: 40px;
  border-bottom: 1px solid rgba(255,255,255,.1);
}
.footer-brand .brand { color: #fff; font-size: 1.1rem; }
.footer-brand p { color: #aaa49a; margin-top: 14px; max-width: 36ch; }
.footer-nav { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; }
.footer-h {
  font-family: var(--font-sans);
  font-size: .82rem;
  text-transform: uppercase;
  letter-spacing: .12em;
  color: #fff;
  margin: 0 0 16px;
  font-weight: 700;
}
.footer-nav ul { list-style: none; padding: 0; margin: 0; display: grid; gap: 10px; }
.footer-nav a { text-decoration: none; color: #cfc9be; font-size: .92rem; }
.footer-nav a:hover { color: #fff; }
.footer-bottom {
  display: flex; justify-content: space-between; gap: 16px;
  padding-top: 24px;
  color: #8a8478; flex-wrap: wrap;
}
.footer-bottom a { color: inherit; }

/* ================= Responsive ================= */
@media (max-width: 1024px) {
  .hero-inner { grid-template-columns: 1fr; gap: 48px; }
  .hero-visual { min-height: 360px; max-width: 520px; }
  .product-grid { grid-template-columns: repeat(3, 1fr); }
  .category-grid { grid-template-columns: repeat(3, 1fr); }
  .deals-grid { grid-template-columns: 1fr 1fr; }
  .deal-feature { grid-row: auto; grid-column: span 2; }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .story-lead { grid-row: auto; grid-column: span 2; }
  .newsletter-inner { grid-template-columns: 1fr; gap: 32px; }
}

@media (max-width: 720px) {
  .primary-nav { display: none; }
  .header-inner { gap: 12px; justify-content: space-between; }
  .product-grid { grid-template-columns: repeat(2, 1fr); gap: 16px; }
  .category-grid { grid-template-columns: repeat(2, 1fr); }
  .deals-grid { grid-template-columns: 1fr; }
  .deal-feature { grid-column: auto; }
  .editorial-grid { grid-template-columns: 1fr; }
  .story-lead { grid-column: auto; }
  .footer-inner { grid-template-columns: 1fr; gap: 32px; }
  .footer-nav { grid-template-columns: repeat(3, 1fr); gap: 16px; }
  .hero-stats { flex-wrap: wrap; gap: 20px; }
  .section-head { align-items: flex-start; }
  .hero { padding: 32px 0 56px; }
  .featured, .deals, .editorial, .newsletter { padding: 56px 0; }
}

@media (max-width: 420px) {
  .footer-nav { grid-template-columns: 1fr 1fr; }
  .newsletter-form { grid-template-columns: 1fr; }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; animation: none !important; }
}

/* Forced colors */
@media (forced-colors: active) {
  .btn-primary, .tab.is-active { border: 1px solid CanvasText; }
  .product, .story, .deal { border: 1px solid CanvasText; }
}
